SELECT o.job_no, COALESCE(o.equipment_id, '') AS equipment_id, o.dispatch_status, 'RESOURCE_BUSY' AS conflict_kind, CONCAT('Another RUNNING job on ', o.equipment_id) AS detail FROM emc_job_order o WHERE o.dispatch_status IN ('ALLOWED','NOT_ALLOWED') AND EXISTS (SELECT 1 FROM emc_job_order r WHERE r.equipment_id = o.equipment_id AND r.dispatch_status = 'RUNNING' AND r.job_no <> o.job_no) UNION ALL SELECT o.job_no, COALESCE(o.equipment_id, '') AS equipment_id, o.dispatch_status, 'CAPABILITY_WINDOW' AS conflict_kind, 'No AVAILABLE operations capability window for equipment' AS detail FROM emc_job_order o WHERE o.dispatch_status IN ('ALLOWED','NOT_ALLOWED') AND o.equipment_id IS NOT NULL AND NOT EXISTS (  SELECT 1 FROM emc_operations_capability c   JOIN emc_ops_capability_equipment ce ON ce.capability_id = c.capability_id   WHERE ce.equipment_id = o.equipment_id AND c.status = 'AVAILABLE'   AND (c.available_from IS NULL OR c.available_from <= CURRENT_TIMESTAMP)   AND (c.available_to IS NULL OR c.available_to >= CURRENT_TIMESTAMP)) ORDER BY job_no
